--   mb_order_code_from_catalogue_part_08  (regler 101–120)
--   mb_order_code_from_catalogue_part_09  (regler 121–140)
--   mb_order_code_from_catalogue_part_10  (regler 141–160)
--   mb_order_code_from_catalogue_part_11  (regler 161–180)
--   mb_order_code_from_catalogue_part_12  (regler 181–197, dokumentkarta, produktspecar)
--   mb_order_code_from_catalogue_part_13  (material sida 484; källösa specen standard = ISO 15552 bort)
--   mb_order_code_from_catalogue_part_14  (SMC-MB namn och beskrivning utan ISO 15552, slag upp till 2700)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts mb):
--   regler  197  md5 87d040bdb65fa376d469591ebf31e411   villkor b26b305e34ce7b846510f69e3920f21a
--   värden  71   md5 4bcccd68101bc861a8e6af5af8814d6c
--   schema       md5 6fe4385833708adb4cec932360590a65
-- Verifierat live: /sv/configurator/mb bygger MDBD32-50Z-NW-M9BW (beställexemplet sida 483),
-- stoppar tappfästet T på ø32 med två M9BW under 75 mm slag (sida 519–520), pivotfästet N
-- på basutförandet B (sida 482) och kabellängden M för D-P4DW (sida 482, —).
--
-- MB: beställnyckeln enligt SMC Air Cylinder MB Series (sida 482–483).
-- GENERERAD ur src/lib/catalog/mb.ts -- redigera inte för hand.
--
-- Rättar familjen mb, som hade mallen 'MB-{bore_mm}-{stroke_mm}-{cushioning}{sensing}'
-- med Festos dämpningskoder. SMC:s kod är
-- M{magnet}B{fäste}{ø}{gänga}-{slag}{dämpning}{bälg}Z-{pivot}{knäled}-{givare}{kabel}{antal}-{special},
-- t.ex. MDBD32-50Z-NW-M9BW (beställexemplet sida 483). Fäste, gänga, bälg,
-- pivotfäste, knäled, givare och specialutföranden fanns inte alls.
--
-- SMC-MB får katalogens borrningar, slag, temperatur, tryck och material;
-- den källösa specen 'standard = ISO 15552' tas bort.

begin;

create schema if not exists backup;
create table if not exists backup.mb_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'mb'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'mb'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'mb';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-MB-V1', '{"version":"1.0","steps":[{"id":"bore","step":1,"title_sv":"Kolvdiameter","title_en":"Bore size","required":true,"type":"single_select","options":[{"v":"32","label":"ø32 mm"},{"v":"40","label":"ø40 mm"},{"v":"50","label":"ø50 mm"},{"v":"63","label":"ø63 mm"},{"v":"80","label":"ø80 mm"},{"v":"100","label":"ø100 mm"},{"v":"125","label":"ø125 mm"}]},{"id":"mounting","step":2,"title_sv":"Fäste","title_en":"Mounting","required":true,"type":"single_select","options":[{"v":"B","label":"Basutförande"},{"v":"L","label":"Fotfäste"},{"v":"F","label":"Fläns vid kolvstången"},{"v":"G","label":"Fläns vid gaveln"},{"v":"C","label":"Enkelt gaffelfäste"},{"v":"D","label":"Dubbelt gaffelfäste"},{"v":"T","label":"Centrerat tappfäste (monterat vid leverans)"}]},{"id":"stroke_mm","step":3,"title_sv":"Slaglängd","title_en":"Cylinder stroke","required":true,"type":"numeric","min":1,"max":2700,"unit":"mm"},{"id":"magnet","step":4,"title_sv":"Inbyggd magnet","title_en":"Built-in magnet","required":false,"type":"single_select","options":[{"v":"D","label":"Inbyggd magnet för givare (MDB)"}]},{"id":"port","step":5,"title_sv":"Portgänga","title_en":"Port thread type","required":false,"type":"single_select","options":[{"v":"TN","label":"Portgänga NPT (standard är Rc)"},{"v":"TF","label":"Portgänga G (standard är Rc)"}]},{"id":"cushion","step":6,"title_sv":"Dämpning (standard är luftdämpning)","title_en":"Cushion (air cushion is standard)","required":false,"type":"single_select","options":[{"v":"N","label":"Gummibuffert i stället för luftdämpning (cylindern blir 6–12 mm längre)"}]},{"id":"boot","step":7,"title_sv":"Bälg","title_en":"Rod boot","required":false,"type":"single_select","options":[{"v":"J","label":"Bälg i nylonduk"},{"v":"K","label":"Värmebeständig bälg"}]},{"id":"pivot","step":8,"title_sv":"Tillbehör 1: pivotfäste","title_en":"Accessory 1: pivot bracket","required":false,"type":"single_select","options":[{"v":"N","label":"Pivotfäste, medföljer (bara dubbelt gaffelfäste D och tappfäste T)"}]},{"id":"knuckle","step":9,"title_sv":"Tillbehör 2: knäled","title_en":"Accessory 2: knuckle joint","required":false,"type":"single_select","options":[{"v":"V","label":"Enkel knäled på kolvstången (sprint ingår inte)"},{"v":"W","label":"Dubbel knäled på kolvstången"}]},{"id":"switch","step":10,"title_sv":"Magnetgivare","title_en":"Auto switch","required":false,"type":"single_select","options":[{"v":"M9N","label":"D-M9N, 3-tråd NPN"},{"v":"M9P","label":"D-M9P, 3-tråd PNP"},{"v":"M9B","label":"D-M9B, 2-tråd"},{"v":"M9NW","label":"D-M9NW, NPN, tvåfärgsindikering"},{"v":"M9PW","label":"D-M9PW, PNP, tvåfärgsindikering"},{"v":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering"},{"v":"M9NA","label":"D-M9NA, NPN, vattentät"},{"v":"M9PA","label":"D-M9PA, PNP, vattentät"},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät"},{"v":"F59F","label":"D-F59F, 4-tråd NPN med diagnosutgång"},{"v":"P3DWA","label":"D-P3DWA, 2-tråd, magnetfältsokänslig"},{"v":"P4DW","label":"D-P4DW, 2-tråd, magnetfältsokänslig"},{"v":"A96","label":"D-A96, reed 3-tråd"},{"v":"A93","label":"D-A93, reed 2-tråd"},{"v":"A90","label":"D-A90, reed utan indikering"},{"v":"A54","label":"D-A54, reed 100/200 V"},{"v":"A64","label":"D-A64, reed 200 V utan indikering"},{"v":"A33","label":"D-A33, reed med plintanslutning (bandmontering)"},{"v":"A34","label":"D-A34, reed med plintanslutning (bandmontering)"},{"v":"A44","label":"D-A44, reed med DIN-plint (bandmontering)"},{"v":"A59W","label":"D-A59W, reed tvåfärgsindikering"}]},{"id":"lead","step":11,"title_sv":"Givarens kabellängd (standard 0,5 m)","title_en":"Lead wire length (0.5 m is standard)","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"}]},{"id":"count","step":12,"title_sv":"Antal givare","title_en":"Number of auto switches","required":false,"type":"single_select","options":[{"v":"S","label":"En givare (standard är två)"},{"v":"3","label":"Tre